CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, nome text NOT NULL DEFAULT 'Novo atleta' CHECK (char_length(nome) BETWEEN 2 AND 100), atuacao text NOT NULL DEFAULT 'Atleta' CHECK (atuacao IN ('Atleta','Treinador','Olheiro')), cidade text NOT NULL DEFAULT '', modalidades text[] NOT NULL DEFAULT '{}', bio text NOT NULL DEFAULT '' CHECK (char_length(bio) <= 2000), avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon; GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_public ON public.profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY profiles_own ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_sports_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,nome) VALUES (NEW.id, left(coalesce(nullif(trim(NEW.raw_user_meta_data->>'nome'),''),'Novo atleta'),100)); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_sports_profile() FROM PUBLIC;
CREATE TRIGGER sports_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_sports_profile();
CREATE TABLE public.podios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, titulo text NOT NULL CHECK(char_length(titulo) BETWEEN 1 AND 200), posicao integer NOT NULL CHECK(posicao IN (1,2,3)), ano integer NOT NULL CHECK(ano BETWEEN 1900 AND 2200));
GRANT SELECT ON public.podios TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.podios TO authenticated; GRANT ALL ON public.podios TO service_role;
ALTER TABLE public.podios ENABLE ROW LEVEL SECURITY;
CREATE POLICY podios_public ON public.podios FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY podios_own ON public.podios FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.marcas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, prova text NOT NULL CHECK(char_length(prova) BETWEEN 1 AND 100), valor text NOT NULL CHECK(char_length(valor) BETWEEN 1 AND 100));
GRANT SELECT ON public.marcas TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.marcas TO authenticated; GRANT ALL ON public.marcas TO service_role;
ALTER TABLE public.marcas ENABLE ROW LEVEL SECURITY;
CREATE POLICY marcas_public ON public.marcas FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY marcas_own ON public.marcas FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), autor uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, tipo text NOT NULL CHECK(tipo IN ('Notícia','Conquista','Treino','Peneira')), texto text NOT NULL CHECK(char_length(trim(texto)) BETWEEN 1 AND 5000), modalidade text NOT NULL, cidade text NOT NULL, image_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.posts TO authenticated; GRANT ALL ON public.posts TO service_role;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY posts_public ON public.posts FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY posts_own ON public.posts FOR ALL TO authenticated USING(autor=auth.uid()) WITH CHECK(autor=auth.uid());
CREATE TABLE public.likes (post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(post_id,user_id));
GRANT SELECT ON public.likes TO anon; GRANT SELECT,INSERT,DELETE ON public.likes TO authenticated; GRANT ALL ON public.likes TO service_role;
ALTER TABLE public.likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_public ON public.likes FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY likes_own ON public.likes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, autor uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, texto text NOT NULL CHECK(char_length(trim(texto)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comments TO anon; GRANT SELECT,INSERT,DELETE ON public.comments TO authenticated; GRANT ALL ON public.comments TO service_role;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_public ON public.comments FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY comments_own ON public.comments FOR ALL TO authenticated USING(autor=auth.uid()) WITH CHECK(autor=auth.uid());
CREATE TABLE public.follows (follower uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, followed uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(follower,followed), CHECK(follower<>followed));
GRANT SELECT ON public.follows TO anon; GRANT SELECT,INSERT,DELETE ON public.follows TO authenticated; GRANT ALL ON public.follows TO service_role;
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY follows_public ON public.follows FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY follows_own ON public.follows FOR ALL TO authenticated USING(follower=auth.uid()) WITH CHECK(follower=auth.uid());
CREATE TABLE public.eventos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organizador uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, nome text NOT NULL CHECK(char_length(trim(nome)) BETWEEN 3 AND 200), modalidade text NOT NULL, cidade text NOT NULL, data date NOT NULL, local text NOT NULL CHECK(char_length(trim(local)) BETWEEN 1 AND 300), vagas integer NOT NULL CHECK(vagas BETWEEN 1 AND 100000), valor text NOT NULL DEFAULT 'Gratuito' CHECK(char_length(valor)<=100), descricao text NOT NULL DEFAULT '' CHECK(char_length(descricao)<=5000), categorias text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.eventos TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.eventos TO authenticated; GRANT ALL ON public.eventos TO service_role;
ALTER TABLE public.eventos ENABLE ROW LEVEL SECURITY;
CREATE POLICY eventos_public ON public.eventos FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY eventos_own ON public.eventos FOR ALL TO authenticated USING(organizador=auth.uid()) WITH CHECK(organizador=auth.uid());
CREATE TABLE public.inscricoes (evento_id uuid NOT NULL REFERENCES public.eventos(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(evento_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.inscricoes TO authenticated; GRANT ALL ON public.inscricoes TO service_role;
ALTER TABLE public.inscricoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY inscricoes_read ON public.inscricoes FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.eventos e WHERE e.id=evento_id AND e.organizador=auth.uid()));
CREATE POLICY inscricoes_own ON public.inscricoes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY inscricoes_delete ON public.inscricoes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.check_event_capacity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE capacity integer; event_day date; BEGIN SELECT vagas,data INTO capacity,event_day FROM public.eventos WHERE id=NEW.evento_id FOR UPDATE; IF capacity IS NULL THEN RAISE EXCEPTION 'Evento não encontrado'; END IF; IF event_day < CURRENT_DATE THEN RAISE EXCEPTION 'Evento encerrado'; END IF; IF EXISTS(SELECT 1 FROM public.inscricoes WHERE evento_id=NEW.evento_id AND user_id=NEW.user_id) THEN RETURN NULL; END IF; IF (SELECT count(*) FROM public.inscricoes WHERE evento_id=NEW.evento_id)>=capacity THEN RAISE EXCEPTION 'Vagas esgotadas'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.check_event_capacity() FROM PUBLIC;
CREATE TRIGGER registration_capacity BEFORE INSERT ON public.inscricoes FOR EACH ROW EXECUTE FUNCTION public.check_event_capacity();
CREATE FUNCTION public.check_capacity_edit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.vagas < (SELECT count(*) FROM public.inscricoes WHERE evento_id=NEW.id) THEN RAISE EXCEPTION 'Vagas inferiores às inscrições existentes'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.check_capacity_edit() FROM PUBLIC;
CREATE TRIGGER event_capacity_edit BEFORE UPDATE ON public.eventos FOR EACH ROW EXECUTE FUNCTION public.check_capacity_edit();
CREATE FUNCTION public.event_counts() RETURNS TABLE(id uuid,inscritos bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id,count(i.user_id) FROM public.eventos e LEFT JOIN public.inscricoes i ON i.evento_id=e.id GROUP BY e.id; $$;
REVOKE ALL ON FUNCTION public.event_counts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.event_counts() TO anon,authenticated,service_role;
CREATE INDEX posts_created_idx ON public.posts(created_at DESC); CREATE INDEX posts_author_idx ON public.posts(autor); CREATE INDEX comments_post_idx ON public.comments(post_id,created_at); CREATE INDEX events_date_idx ON public.eventos(data); CREATE INDEX follows_target_idx ON public.follows(followed); CREATE INDEX podios_user_idx ON public.podios(user_id); CREATE INDEX marcas_user_idx ON public.marcas(user_id); CREATE INDEX registrations_user_idx ON public.inscricoes(user_id);
CREATE POLICY sports_media_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='sports-media' AND (EXISTS(SELECT 1 FROM public.profiles p WHERE p.avatar_path=name) OR EXISTS(SELECT 1 FROM public.posts p WHERE p.image_path=name) OR (storage.foldername(name))[1]=auth.uid()::text));
CREATE POLICY sports_media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='sports-media' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY sports_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='sports-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE FUNCTION public.check_sports_media_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE path text; owner_id uuid; BEGIN IF TG_TABLE_NAME='profiles' THEN path:=NEW.avatar_path; owner_id:=NEW.id; ELSE path:=NEW.image_path; owner_id:=NEW.autor; END IF; IF path IS NOT NULL AND split_part(path,'/',1)<>owner_id::text THEN RAISE EXCEPTION 'Imagem de outra conta'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.check_sports_media_owner() FROM PUBLIC;
CREATE TRIGGER profile_media_owner BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.check_sports_media_owner();
CREATE TRIGGER post_media_owner BEFORE INSERT OR UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.check_sports_media_owner();